import pytest
import sys
from pathlib import Path

# Add parent directory to path to import the ai module
sys.path.insert(0, str(Path(__file__).parent.parent))

from ai import learning


class TestAILearning:
    """Test suite for AI learning module."""

    def test_module_exists(self):
        """Verify the learning module can be imported."""
        assert learning is not None

    def test_tokenize_code_basic(self):
        """Test basic code tokenization if function exists."""
        if hasattr(learning, 'tokenize_code'):
            code = "def hello(): return 42"
            tokens = learning.tokenize_code(code)
            assert isinstance(tokens, list)
            assert len(tokens) > 0

    def test_tokenize_code_operators(self):
        """Test tokenization of operators if function exists."""
        if hasattr(learning, 'tokenize_code'):
            code = "x == y and z >= 10"
            tokens = learning.tokenize_code(code)
            assert '==' in tokens or 'x' in tokens

    def test_tokenize_code_empty(self):
        """Test tokenization of empty string if function exists."""
        if hasattr(learning, 'tokenize_code'):
            code = ""
            tokens = learning.tokenize_code(code)
            assert isinstance(tokens, list)

    def test_vocab_exists(self):
        """Test if vocabulary is built if it exists."""
        if hasattr(learning, 'vocab'):
            assert learning.vocab is not None
            assert isinstance(learning.vocab, (list, set, dict))

    def test_stoi_mapping(self):
        """Test string-to-index mapping if it exists."""
        if hasattr(learning, 'stoi'):
            assert learning.stoi is not None
            assert isinstance(learning.stoi, dict)

    def test_itos_mapping(self):
        """Test index-to-string mapping if it exists."""
        if hasattr(learning, 'itos'):
            assert learning.itos is not None
            assert isinstance(learning.itos, dict)

    def test_vocab_size(self):
        """Test vocabulary size if it exists."""
        if hasattr(learning, 'vocab_size'):
            assert learning.vocab_size is not None
            assert isinstance(learning.vocab_size, int)
            assert learning.vocab_size >= 0

    def test_data_ids_format(self):
        """Test data IDs format if they exist."""
        if hasattr(learning, 'data_ids'):
            assert learning.data_ids is not None
            assert isinstance(learning.data_ids, (list, tuple))

    def test_training_data_exists(self):
        """Test if training data arrays exist."""
        if hasattr(learning, 'xs'):
            assert learning.xs is not None
        if hasattr(learning, 'ys'):
            assert learning.ys is not None


class TestAILearningIntegration:
    """Integration tests for AI learning module."""

    def test_tokenize_and_vocab_consistency(self):
        """Test consistency between tokenization and vocabulary if both exist."""
        if hasattr(learning, 'tokenize_code') and hasattr(learning, 'vocab'):
            code = "def test(): pass"
            tokens = learning.tokenize_code(code)
            # Tokens should be compatible with vocab structure
            assert isinstance(tokens, list)

    def test_stoi_itos_inverse(self):
        """Test that stoi and itos are inverse mappings if both exist."""
        if hasattr(learning, 'stoi') and hasattr(learning, 'itos'):
            if learning.stoi and learning.itos:
                # Pick a sample token
                for token, idx in list(learning.stoi.items())[:5]:
                    assert learning.itos.get(idx) == token

    def test_vocab_size_matches_vocab(self):
        """Test that vocab_size matches actual vocabulary length if both exist."""
        if hasattr(learning, 'vocab') and hasattr(learning, 'vocab_size'):
            if learning.vocab:
                assert learning.vocab_size == len(learning.vocab)


if __name__ == "__main__":
    pytest.main([__file__, "-v"])
```
